SPANNER = "spanner"


def _by_type(objects):
    t = {}
    try:
        items = list(objects)
    except Exception:
        items = []
    for pair in items:
        try:
            name, typ = pair[0], pair[1]
        except Exception:
            continue
        t.setdefault(str(typ), []).append(str(name))
    for v in t.values():
        v.sort()
    return t


def _norm(facts):
    out = set()
    try:
        it = list(facts)
    except Exception:
        return out
    for f in it:
        try:
            out.add(tuple(str(x) for x in f))
        except Exception:
            continue
    return out


def _loc_of(state, thing):
    return set(a[2] for a in state if a[0] == "at" and a[1] == thing)


def _actions(state, men, spanners, nuts, locs):
